package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.os.Build;import android.widget.RemoteViews;
public class LocalClockWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){boolean analog=c.getSharedPreferences("clock_tools",Context.MODE_PRIVATE).getBoolean("clock_face_analog",false)&&Build.VERSION.SDK_INT>=31;int layout=analog?R.layout.widget_local_clock_analog:R.layout.widget_local_clock;RemoteViews r=new RemoteViews(c.getPackageName(),layout);boolean h24=c.getSharedPreferences("clock_tools",Context.MODE_PRIVATE).getBoolean("use_24h",true);if(!analog){r.setCharSequence(R.id.widget_time,"setFormat24Hour",h24?"HH:mm":"hh:mm a");r.setCharSequence(R.id.widget_time,"setFormat12Hour",h24?"HH:mm":"hh:mm a");}r.setCharSequence(R.id.widget_date,"setFormat24Hour","M/d EEE");r.setCharSequence(R.id.widget_date,"setFormat12Hour","M/d EEE");r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,ClockActivity.class,"mode","world",21000+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
